// Engine manages active and historical bracket orders in-memory and persists them to Store.
type Engine struct {
	mu                 sync.RWMutex
	store              Store
	placeOrder         func(ctx context.Context, o kotakapi.Order) (string, error)
	cancelOrder        func(ctx context.Context, id string) error
	log                *slog.Logger
	brackets           map[string]*Bracket
	onChange           func(b Bracket)
	activeInPos        atomic.Int64
	activeByInstrument map[string]map[string]*Bracket
	asyncExecution     bool
	unmatchedOrders    map[string]parsedOrder
}

// SetAsync configures whether OnTick executes triggers in asynchronous background goroutines.
func (e *Engine) SetAsync(async bool) {
	e.mu.Lock()
	e.asyncExecution = async
	e.mu.Unlock()
}

// NewEngine creates a new bracket and OCO engine.
func NewEngine(
	store Store,
	placeOrder func(ctx context.Context, o kotakapi.Order) (string, error),
	cancelOrder func(ctx context.Context, id string) error,
	log *slog.Logger,
) *Engine {
	if log == nil {
		log = slog.Default()
	}
	e := &Engine{
		store:              store,
		placeOrder:         placeOrder,
		cancelOrder:        cancelOrder,
		log:                log,
		brackets:           make(map[string]*Bracket),
		activeByInstrument: make(map[string]map[string]*Bracket),
		unmatchedOrders:    make(map[string]parsedOrder),
	}

	if store != nil {
		// Load active brackets from store on startup
		if activeStore, ok := store.(ActiveStore); ok {
			if active, err := activeStore.GetActiveBrackets(context.Background()); err == nil {
				for i := range active {
					b := active[i]
					bp := &b
					e.brackets[b.ID] = bp
					if b.Status == StatusInPosition {
						e.indexActiveInPosition(bp)
					}
				}
			} else {
				e.log.Warn("failed to load active brackets from activeStore", "error", err)
			}
		} else if list, err := store.ListBrackets(context.Background(), 1000); err == nil {
			for i := range list {
				b := list[i]
				if b.Status == StatusPendingEntry || b.Status == StatusInPosition {
					bp := &b
					e.brackets[b.ID] = bp
					if b.Status == StatusInPosition {
						e.indexActiveInPosition(bp)
					}
				}
			}
		} else {
			e.log.Warn("failed to load brackets from store", "error", err)
		}
	}

	return e
}

func (e *Engine) indexActiveInPosition(b *Bracket) {
	m, ok := e.activeByInstrument[b.InstrumentKey]
	if !ok {
		m = make(map[string]*Bracket)
		e.activeByInstrument[b.InstrumentKey] = m
	}
	if _, exists := m[b.ID]; !exists {
		m[b.ID] = b
		e.activeInPos.Add(1)
	}
}

func (e *Engine) unindexActiveInPosition(b *Bracket) {
	if m, ok := e.activeByInstrument[b.InstrumentKey]; ok {
		if _, exists := m[b.ID]; exists {
			delete(m, b.ID)
			if len(m) == 0 {
				delete(e.activeByInstrument, b.InstrumentKey)
			}
			e.activeInPos.Add(-1)
		}
	}
}

// SetOnChange configures the callback invoked when a bracket is created or updated.
func (e *Engine) SetOnChange(fn func(b Bracket)) {
	e.mu.Lock()
	e.onChange = fn
	e.mu.Unlock()
}

// OnChange is an alias for SetOnChange.
func (e *Engine) OnChange(fn func(b Bracket)) {
	e.SetOnChange(fn)
}

// Subscribe is an alias for SetOnChange.
func (e *Engine) Subscribe(fn func(b Bracket)) {
	e.SetOnChange(fn)
}

func (e *Engine) notify(b Bracket) {
	e.mu.RLock()
	fn := e.onChange
	e.mu.RUnlock()

	if fn != nil {
		fn(b)
	}
}

// Create validates and registers a new bracket order, placing entry order if necessary.
func (e *Engine) Create(ctx context.Context, b Bracket) (*Bracket, error) {
	if strings.TrimSpace(b.ExchangeSegment) == "" {
		return nil, errors.New("bracket: exchange segment is required")
	}
	if strings.TrimSpace(b.TradingSymbol) == "" {
		return nil, errors.New("bracket: trading symbol is required")
	}
	if strings.TrimSpace(b.InstrumentKey) == "" {
		return nil, errors.New("bracket: instrument key is required")
	}
	if b.Quantity <= 0 {
		return nil, errors.New("bracket: quantity must be positive")
	}
	if b.EntryPrice < 0 {
		return nil, errors.New("bracket: entry price cannot be negative")
	}
	if b.TargetPrice < 0 {
		return nil, errors.New("bracket: target price cannot be negative")
	}
	if b.StopLossPrice < 0 {
		return nil, errors.New("bracket: stoploss price cannot be negative")
	}

	tt := strings.ToUpper(strings.TrimSpace(b.TransactionType))
	switch tt {
	case "B", "BUY":
		tt = "BUY"
	case "S", "SELL":
		tt = "SELL"
	default:
		return nil, errors.New("bracket: transaction type must be BUY or SELL")
	}
	b.TransactionType = tt

	// Validate target and stoploss directional price sanity
	if b.TransactionType == "BUY" {
		if b.TargetPrice > 0 && b.EntryPrice > 0 && b.TargetPrice <= b.EntryPrice {
			return nil, errors.New("bracket: target price must be greater than entry price for BUY")
		}
		if b.StopLossPrice > 0 && b.EntryPrice > 0 && b.StopLossPrice >= b.EntryPrice {
			return nil, errors.New("bracket: stoploss price must be less than entry price for BUY")
		}
		if b.TargetPrice > 0 && b.StopLossPrice > 0 && b.TargetPrice <= b.StopLossPrice {
			return nil, errors.New("bracket: target price must be greater than stoploss price for BUY")
		}
	} else if b.TransactionType == "SELL" {
		if b.TargetPrice > 0 && b.EntryPrice > 0 && b.TargetPrice >= b.EntryPrice {
			return nil, errors.New("bracket: target price must be less than entry price for SELL")
		}
		if b.StopLossPrice > 0 && b.EntryPrice > 0 && b.StopLossPrice <= b.EntryPrice {
			return nil, errors.New("bracket: stoploss price must be greater than entry price for SELL")
		}
		if b.TargetPrice > 0 && b.StopLossPrice > 0 && b.TargetPrice >= b.StopLossPrice {
			return nil, errors.New("bracket: target price must be less than stoploss price for SELL")
		}
	}

	prod := strings.ToUpper(strings.TrimSpace(b.Product))
	if prod == "" {
		prod = "MIS"
	}
	b.Product = prod

	if b.ID == "" {
		b.ID = generateID()
	}
	if b.Status == "" {
		b.Status = StatusPendingEntry
	}

	now := time.Now()
	if b.CreatedAt.IsZero() {
		b.CreatedAt = now
	}
	b.UpdatedAt = now

	// Pre-register bracket in memory so fast WebSocket fill events arriving in 10-20ms will match
	e.mu.Lock()
	bracketCopy := b
	e.brackets[b.ID] = &bracketCopy
	e.mu.Unlock()

	// If entry order has not yet been placed and bracket is in PENDING_ENTRY, submit it
	if b.Status == StatusPendingEntry && b.EntryOrderID == "" && e.placeOrder != nil {
		orderType := "L"
		if b.EntryPrice <= 0 {
			orderType = "MKT"
		}
		o := kotakapi.Order{
			Tag:             b.ID,
			ExchangeSegment: b.ExchangeSegment,
			TradingSymbol:   b.TradingSymbol,
			TransactionType: b.TransactionType,
			Product:         b.Product,
			OrderType:       orderType,
			Quantity:        b.Quantity,
			Price:           b.EntryPrice,
			Validity:        "GFD",
		}
		orderID, err := e.placeOrder(ctx, o)
		if err != nil {
			e.mu.Lock()
			delete(e.brackets, b.ID)
			e.mu.Unlock()
			return nil, fmt.Errorf("bracket: place entry order: %w", err)
		}

		e.mu.Lock()
		b.EntryOrderID = orderID
		if curr, ok := e.brackets[b.ID]; ok {
			curr.EntryOrderID = orderID
			// Check if fill arrived over WebSocket while HTTP placeOrder was returning
			if unmatched, found := e.unmatchedOrders[orderID]; found {
				delete(e.unmatchedOrders, orderID)
				if isFilledStatus(unmatched.Status) {
					curr.Status = StatusInPosition
					if unmatched.FilledPrice > 0 {
						curr.EntryPrice = unmatched.FilledPrice
					}
					curr.UpdatedAt = time.Now()
					e.indexActiveInPosition(curr)
				}
			}
			bracketCopy = *curr
		}
		e.mu.Unlock()
	} else {
		e.mu.Lock()
		if bracketCopy.Status == StatusInPosition {
			e.indexActiveInPosition(&bracketCopy)
		}
		e.mu.Unlock()
	}

	if e.store != nil {
		if err := e.store.CreateBracket(ctx, bracketCopy); err != nil {
			e.log.Error("failed to persist bracket in store", "id", b.ID, "error", err)
		}
	}

	e.notify(bracketCopy)
	return &bracketCopy, nil
}

// Cancel cancels a pending bracket, cancelling any resting entry order.
func (e *Engine) Cancel(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status == StatusInPosition {
		e.mu.Unlock()
		return errors.New("cannot cancel active in-position bracket; use exit to square off")
	}
	if b.Status != StatusPendingEntry {
		currStatus := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be cancelled in status %s", id, currStatus)
	}

	orderToCancel := b.EntryOrderID
	e.unindexActiveInPosition(b)
	b.Status = StatusCancelled
	b.UpdatedAt = time.Now()
	bracketCopy := *b
	e.mu.Unlock()

	if orderToCancel != "" && e.cancelOrder != nil {
		if err := e.cancelOrder(ctx, orderToCancel); err != nil {
			e.log.Warn("failed to cancel order on bracket cancel", "id", id, "order_id", orderToCancel, "error", err)
		}
	}

	if e.store != nil {
		if err := e.store.UpdateBracket(ctx, bracketCopy); err != nil {
			e.log.Error("failed to update bracket on cancel in store", "id", id, "error", err)
		}
	}

	e.notify(bracketCopy)
	return nil
}

// Disarm marks an active or pending bracket as externally squared off/cancelled
// without placing duplicate market exit orders.
func (e *Engine) Disarm(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	e.unindexActiveInPosition(b)
	if b.Status == StatusPendingEntry {
		b.Status = StatusCancelled
	} else {
		b.Status = StatusExitedManual
	}
	b.UpdatedAt = time.Now()
	bracketCopy := *b
	e.mu.Unlock()

	if e.store != nil {
		_ = e.store.UpdateBracket(ctx, bracketCopy)
	}
	e.notify(bracketCopy)
	return nil
}

// Exit squares off a bracket manually by cancelling resting orders and placing a market exit order.
func (e *Engine) Exit(ctx context.Context, id string) error {
	e.mu.Lock()
	b, ok := e.brackets[id]
	if !ok {
		e.mu.Unlock()
		return errors.New("bracket not found")
	}
	if b.Status != StatusPendingEntry && b.Status != StatusInPosition && b.Status != StatusExitFailed {
		currStatus := b.Status
		e.mu.Unlock()
		return fmt.Errorf("bracket %s cannot be exited in status %s", id, currStatus)
	}

	if b.Status == StatusPendingEntry {
		// Entry not filled; cancel entry order and cancel bracket
		orderToCancel := b.EntryOrderID
		b.Status = StatusCancelled
		b.UpdatedAt = time.Now()
		bracketCopy := *b
		e.mu.Unlock()

		if orderToCancel != "" && e.cancelOrder != nil {
			_ = e.cancelOrder(ctx, orderToCancel)
		}
		if e.store != nil {
			_ = e.store.UpdateBracket(ctx, bracketCopy)
		}
		e.notify(bracketCopy)
		return nil
	}

	// In position or failed exit: cancel resting exit order if any, and execute market exit
	e.unindexActiveInPosition(b)
	restingOrder := b.ExitOrderID
	b.Status = StatusExitedManual
	b.UpdatedAt = time.Now()

	exitSide := "SELL"
	if strings.ToUpper(b.TransactionType) == "SELL" {
		exitSide = "BUY"
	}
	exitOrder := kotakapi.Order{
		Tag:             "exit_" + b.ID,
		ExchangeSegment: b.ExchangeSegment,
		TradingSymbol:   b.TradingSymbol,
		TransactionType: exitSide,
		Product:         b.Product,
		OrderType:       "MKT",
		Quantity:        b.Quantity,
		Validity:        "GFD",
	}
	bracketCopy := *b
	e.mu.Unlock()

	ctx = kotakhttp.WithPriority(ctx)

	if restingOrder != "" && e.cancelOrder != nil {
		_ = e.cancelOrder(ctx, restingOrder)
	}

	var exitErr error
	var orderID string
	if e.placeOrder != nil {
	exitRetryLoop:
		for attempt := 0; attempt < 3; attempt++ {
			if attempt > 0 {
				select {
				case <-ctx.Done():
					exitErr = ctx.Err()
					break exitRetryLoop
				case <-time.After(50 * time.Millisecond):
				}
			}
			orderID, exitErr = e.placeOrder(ctx, exitOrder)
			if exitErr == nil && orderID != "" {
				break exitRetryLoop
			}
		}
	}

	e.mu.Lock()
	if curr, ok := e.brackets[id]; ok {
		if exitErr != nil {
			e.log.Error("CRITICAL: failed to place exit order on manual exit", "id", id, "error", exitErr)
			curr.Status = StatusExitFailed
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr) // re-index so user or engine can retry exit
			bracketCopy = *curr
		} else {
			curr.ExitOrderID = orderID
			if unmatched, found := e.unmatchedOrders[orderID]; found {
				delete(e.unmatchedOrders, orderID)
				if isFilledStatus(unmatched.Status) {
					curr.Status = StatusExitedManual
					if unmatched.FilledPrice > 0 {
						curr.ExitPrice = unmatched.FilledPrice
					}
				}
			}
			bracketCopy = *curr
		}
	}
	e.mu.Unlock()

	if e.store != nil {
		_ = e.store.UpdateBracket(ctx, bracketCopy)
	}
	e.notify(bracketCopy)
	if exitErr != nil {
		return fmt.Errorf("failed to execute market exit order: %w", exitErr)
	}
	return nil
}

// List returns stored and active brackets up to limit, ordered newest first.
func (e *Engine) List(limit int) ([]Bracket, error) {
	e.mu.RLock()
	defer e.mu.RUnlock()

	result := make([]Bracket, 0, len(e.brackets))
	for _, b := range e.brackets {
		result = append(result, *b)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i].CreatedAt.After(result[j].CreatedAt)
	})

	if limit > 0 && len(result) > limit {
		result = result[:limit]
	}
	return result, nil
}

// Get looks up a bracket by ID from in-memory cache.
func (e *Engine) Get(id string) (*Bracket, bool) {
	e.mu.RLock()
	defer e.mu.RUnlock()

	b, ok := e.brackets[id]
	if !ok {
		return nil, false
	}
	bracketCopy := *b
	return &bracketCopy, true
}

// OnOrderEvent processes an order feed event and updates bracket position state when entry/exit orders fill.
func (e *Engine) OnOrderEvent(ctx context.Context, event orderfeed.Event) {
	if len(event.Data) == 0 {
		return
	}

	orders := parseOrderData(event.Data)
	for _, ord := range orders {
		e.handleOrderUpdate(ctx, ord)
	}
}

type parsedOrder struct {
	OrderID     string
	Tag         string
	Status      string
	FilledPrice float64
}

func parseOrderData(data json.RawMessage) []parsedOrder {
	trimmed := strings.TrimSpace(string(data))
	if strings.HasPrefix(trimmed, "[") {
		var list []map[string]any
		if err := json.Unmarshal(data, &list); err == nil {
			var res []parsedOrder
			for _, item := range list {
				if po, ok := extractParsedOrder(item); ok {
					res = append(res, po)
				}
			}
			return res
		}
	}

	var single map[string]any
	if err := json.Unmarshal(data, &single); err == nil {
		if po, ok := extractParsedOrder(single); ok {
			return []parsedOrder{po}
		}
	}
	return nil
}

func extractParsedOrder(m map[string]any) (parsedOrder, bool) {
	var po parsedOrder

	// Check order ID fields
	for _, k := range []string{"order_id", "nOrdNo", "nordno", "ordId", "ordid", "broker_order_id", "client_order_id", "id"} {
		if v, ok := m[k]; ok && v != nil {
			str := fmt.Sprint(v)
			if str != "" && str != "—" && str != "<nil>" {
				po.OrderID = str
				break
			}
		}
	}
	// Check tag / correlation ID fields
	for _, k := range []string{"tag", "client_order_id", "guiOrdId", "gui_order_id", "tag_id"} {
		if v, ok := m[k]; ok && v != nil {
			str := strings.TrimSpace(fmt.Sprint(v))
			if str != "" && str != "—" && str != "<nil>" {
				po.Tag = str
				break
			}
		}
	}
	if po.OrderID == "" && po.Tag == "" {
		return po, false
	}

	// Check status fields
	for _, k := range []string{"status", "ordSt", "ordst", "order_status"} {
		if v, ok := m[k]; ok && v != nil {
			po.Status = strings.ToUpper(strings.TrimSpace(fmt.Sprint(v)))
			break
		}
	}

	// Check filled price fields
	for _, k := range []string{"avgPrc", "avgprc", "avg_price", "average_price", "price", "prc"} {
		if v, ok := m[k]; ok && v != nil {
			switch val := v.(type) {
			case float64:
				po.FilledPrice = val
			case int64:
				po.FilledPrice = float64(val)
			case int:
				po.FilledPrice = float64(val)
			case string:
				if p, err := strconv.ParseFloat(val, 64); err == nil {
					po.FilledPrice = p
				}
			}
			if po.FilledPrice > 0 {
				break
			}
		}
	}

	return po, true
}

func isFilledStatus(status string) bool {
	switch strings.ToUpper(status) {
	case "TRAD", "COMPLETE", "EXECUTED", "FILLED":
		return true
	default:
		return false
	}
}

func isCancelledStatus(status string) bool {
	switch strings.ToUpper(status) {
	case "CAN", "CANCELLED", "REJ", "REJECTED", "EXPIRED":
		return true
	default:
		return false
	}
}

func (e *Engine) handleOrderUpdate(ctx context.Context, ord parsedOrder) {
	e.mu.Lock()
	var updated *Bracket
	matched := false
	for _, b := range e.brackets {
		isEntryMatch := (b.EntryOrderID == ord.OrderID && ord.OrderID != "") || (ord.Tag != "" && ord.Tag == b.ID)
		if isEntryMatch && (b.Status == StatusPendingEntry || b.Status == "") {
			matched = true
			if isFilledStatus(ord.Status) {
				b.Status = StatusInPosition
				if ord.FilledPrice > 0 {
					b.EntryPrice = ord.FilledPrice
				}
				b.UpdatedAt = time.Now()
				e.indexActiveInPosition(b)
				cp := *b
				updated = &cp
				break
			} else if isCancelledStatus(ord.Status) {
				b.Status = StatusCancelled
				b.UpdatedAt = time.Now()
				cp := *b
				updated = &cp
				break
			}
		}

		isExitMatch := (b.ExitOrderID == ord.OrderID && ord.OrderID != "") || (ord.Tag != "" && ord.Tag == "exit_"+b.ID)
		if isExitMatch {
			matched = true
			if isFilledStatus(ord.Status) {
				e.unindexActiveInPosition(b)
				if ord.FilledPrice > 0 {
					b.ExitPrice = ord.FilledPrice
					if b.TransactionType == "BUY" {
						b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
					} else {
						b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
					}
				}
				b.UpdatedAt = time.Now()
				cp := *b
				updated = &cp
				break
			} else if isCancelledStatus(ord.Status) {
				e.log.Error("CRITICAL: exit order was rejected or cancelled by broker",
					"bracket_id", b.ID, "order_id", ord.OrderID, "status", ord.Status)
				b.Status = StatusExitFailed
				b.UpdatedAt = time.Now()
				e.indexActiveInPosition(b) // re-index to enable manual exit or retry
				cp := *b
				updated = &cp
				break
			}
		}
	}
	if !matched && ord.OrderID != "" {
		if e.unmatchedOrders == nil {
			e.unmatchedOrders = make(map[string]parsedOrder)
		}
		e.unmatchedOrders[ord.OrderID] = ord
		if len(e.unmatchedOrders) > 200 {
			for k := range e.unmatchedOrders {
				delete(e.unmatchedOrders, k)
				break
			}
		}
	}
	e.mu.Unlock()

	if updated != nil {
		if e.store != nil {
			if err := e.store.UpdateBracket(ctx, *updated); err != nil {
				e.log.Error("failed to update bracket on order event", "id", updated.ID, "error", err)
			}
		}
		e.notify(*updated)
	}
}

type tickTrigger struct {
	bracketID    string
	exitSide     string
	exitQuantity int64
	segment      string
	symbol       string
	product      string
	restingOrder string
	newStatus    string
	exitPrice    float64
	pnl          float64
}

// OnTick evaluates current market price against active IN_POSITION brackets, triggering target or stoploss exits.
func (e *Engine) OnTick(ctx context.Context, instrumentKey string, ltp float64) {
	if instrumentKey == "" || ltp <= 0 {
		return
	}
	if e.activeInPos.Load() == 0 {
		return
	}

	var triggers []tickTrigger

	e.mu.Lock()
	activeMap := e.activeByInstrument[instrumentKey]
	if len(activeMap) == 0 {
		e.mu.Unlock()
		return
	}

	for _, b := range activeMap {
		if b.Status != StatusInPosition && b.Status != StatusExitFailed {
			continue
		}

		isLong := b.TransactionType == "BUY"

		// Dynamic trailing stop adjustment
		if b.TrailingStop > 0 {
			trailed := false
			if isLong {
				trailSL := ltp - b.TrailingStop
				if trailSL > b.StopLossPrice {
					b.StopLossPrice = trailSL
					b.UpdatedAt = time.Now()
					trailed = true
				}
			} else {
				trailSL := ltp + b.TrailingStop
				if b.StopLossPrice == 0 || trailSL < b.StopLossPrice {
					b.StopLossPrice = trailSL
					b.UpdatedAt = time.Now()
					trailed = true
				}
			}
			if trailed && e.store != nil {
				cp := *b
				go func(br Bracket) {
					_ = e.store.UpdateBracket(context.Background(), br)
				}(cp)
			}
		}

		hitStatus := ""
		if isLong {
			if b.TargetPrice > 0 && ltp >= b.TargetPrice {
				hitStatus = StatusTargetHit
			} else if b.StopLossPrice > 0 && ltp <= b.StopLossPrice {
				hitStatus = StatusSLHit
			}
		} else {
			if b.TargetPrice > 0 && ltp <= b.TargetPrice {
				hitStatus = StatusTargetHit
			} else if b.StopLossPrice > 0 && ltp >= b.StopLossPrice {
				hitStatus = StatusSLHit
			}
		}

		if hitStatus == "" {
			continue
		}

		// Mutate status under lock immediately so duplicate ticks will not re-trigger exit
		b.Status = hitStatus
		b.ExitPrice = ltp
		if isLong {
			b.PnL = (b.ExitPrice - b.EntryPrice) * float64(b.Quantity)
		} else {
			b.PnL = (b.EntryPrice - b.ExitPrice) * float64(b.Quantity)
		}
		b.UpdatedAt = time.Now()

		exitSide := "SELL"
		if !isLong {
			exitSide = "BUY"
		}

		triggers = append(triggers, tickTrigger{
			bracketID:    b.ID,
			exitSide:     exitSide,
			exitQuantity: b.Quantity,
			segment:      b.ExchangeSegment,
			symbol:       b.TradingSymbol,
			product:      b.Product,
			restingOrder: b.ExitOrderID,
			newStatus:    hitStatus,
			exitPrice:    b.ExitPrice,
			pnl:          b.PnL,
		})
	}
	for _, trg := range triggers {
		if b, ok := e.brackets[trg.bracketID]; ok {
			e.unindexActiveInPosition(b)
		}
	}
	isAsync := e.asyncExecution
	e.mu.Unlock()

	for _, trg := range triggers {
		if isAsync {
			trgCopy := trg
			go e.processTriggerExit(ctx, trgCopy)
		} else {
			e.processTriggerExit(ctx, trg)
		}
	}
}

func (e *Engine) processTriggerExit(ctx context.Context, trg tickTrigger) {
	if ctx == nil {
		ctx = context.Background()
	}
	ctx = kotakhttp.WithPriority(ctx)
	if trg.restingOrder != "" && e.cancelOrder != nil {
		if err := e.cancelOrder(ctx, trg.restingOrder); err != nil {
			e.log.Warn("failed to cancel resting order on bracket trigger", "bracket_id", trg.bracketID, "order_id", trg.restingOrder, "error", err)
		}
	}

	var placedOrderID string
	var placeErr error
	if e.placeOrder != nil {
		exitOrder := kotakapi.Order{
			Tag:             "exit_" + trg.bracketID,
			ExchangeSegment: trg.segment,
			TradingSymbol:   trg.symbol,
			TransactionType: trg.exitSide,
			Product:         trg.product,
			OrderType:       "MKT",
			Quantity:        trg.exitQuantity,
			Validity:        "GFD",
		}
	triggerRetryLoop:
		for attempt := 0; attempt < 3; attempt++ {
			if attempt > 0 {
				select {
				case <-ctx.Done():
					placeErr = ctx.Err()
					break triggerRetryLoop
				case <-time.After(50 * time.Millisecond):
				}
			}
			placedOrderID, placeErr = e.placeOrder(ctx, exitOrder)
			if placeErr == nil && placedOrderID != "" {
				break triggerRetryLoop
			}
		}
	}

	e.mu.Lock()
	var notified Bracket
	if curr, ok := e.brackets[trg.bracketID]; ok {
		if placeErr != nil {
			e.log.Error("CRITICAL: market exit order failed; transitioning to EXIT_FAILED",
				"bracket_id", trg.bracketID, "error", placeErr)
			curr.Status = StatusExitFailed
			curr.UpdatedAt = time.Now()
			e.indexActiveInPosition(curr) // re-index to allow retry or manual square-off
		} else {
			curr.Status = trg.newStatus
			curr.ExitOrderID = placedOrderID
			curr.UpdatedAt = time.Now()
			if unmatched, found := e.unmatchedOrders[placedOrderID]; found {
				delete(e.unmatchedOrders, placedOrderID)
				if isFilledStatus(unmatched.Status) {
					if unmatched.FilledPrice > 0 {
						curr.ExitPrice = unmatched.FilledPrice
						if curr.TransactionType == "BUY" {
							curr.PnL = (curr.ExitPrice - curr.EntryPrice) * float64(curr.Quantity)
						} else {
							curr.PnL = (curr.EntryPrice - curr.ExitPrice) * float64(curr.Quantity)
						}
					}
				}
			}
		}
		notified = *curr
	}
	e.mu.Unlock()

	if e.store != nil {
		if err := e.store.UpdateBracket(ctx, notified); err != nil {
			e.log.Error("failed to persist bracket exit in store", "bracket_id", trg.bracketID, "error", err)
		}
	}

	e.notify(notified)
}

func generateID() string {
	b := make([]byte, 8)
	_, _ = rand.Read(b)
	return fmt.Sprintf("brk_%s", hex.EncodeToString(b))
}
